\title{Two Regimes for the 2-Torsion of a Quadratic Twist Family,\\
and the Collapse of the 3-Division Count}
\author{Aristotle}
\date{4 September 2026}

\begin{document}
\maketitle

\begin{abstract}
Let $p$ be an odd prime and let $a \in \FF_p^{\times}$. We study the quadratic twist family of elliptic curves
$E_{a,d} : y^2 = x^3 - a d^2 x$, $d \in \FF_p^{\times}$, and prove a complete, unconditional dichotomy for its
$2$-torsion. The subgroup $E_{a,d}(\FF_p)[2]$ is a Klein four-group $\ZZ/2 \times \ZZ/2$ when $a$ is a quadratic
residue mod $p$, and is cyclic of order two otherwise --- uniformly in the twisting parameter $d$, because $a d^2$
is a square exactly when $a$ is. Consequently the summed $2$-torsion order over the family equals $4(p-1)$ in the
split regime and $2(p-1)$ in the non-split regime, with no intermediate value possible. Specialising the arithmetic
input to the classical reciprocity laws yields explicit congruence criteria: for $a = 3$ the split classes are
$p \equiv 1, 11 \pmod{12}$; for $a = 2$ they are $p \equiv 1, 7 \pmod 8$; for $a = -1$ they are $p \equiv 1 \pmod 4$.
Both regimes are proved unconditionally, together with the group-theoretic upgrade (the torsion subgroup is
genuinely Klein four, not merely of order four) and the Lagrange consequence $4 \mid \#E_{a,d}(\FF_p)$ in the split
regime, $2 \mid \#E_{a,d}(\FF_p)$ always.

We then contrast this with the analogous computation one level up. For the $j=0$ family $C_b : y^2 = x^3 + b$,
$b \in \FF_p^{\times}$, the $3$-division polynomial is $\psi_3^{(b)}(x) = 3x^4 + 12bx = 3x(x^3+4b)$, whose root
count over $\FF_p$ oscillates between $1$, $2$ and $4$ according to $p \bmod 3$ and the cubic character of $-4b$.
Nevertheless the summed count is regime-independent:
$\sum_{b \neq 0} \#\{x \in \FF_p : \psi_3^{(b)}(x) = 0\} = 2(p-1)$ for every prime $p \neq 2,3$. The proof is a
fibre-counting bijection over the variable $x$ rather than over $b$. The juxtaposition isolates precisely which
input in such a summed count is arithmetic (a quadratic character, hence a congruence condition) and which is
purely combinatorial (a change of variables that averages the arithmetic away).
\end{abstract}

\medskip
\noindent\textbf{Keywords.} elliptic curves over finite fields, $2$-torsion, Klein four-group, quadratic twist,
quadratic reciprocity, division polynomial, fibre counting, cubic residues.

\section{Introduction}

\subsection{The question}

For an elliptic curve $E$ over a finite field $\FF_p$, the torsion subgroups $E(\FF_p)[n]$ encode a great deal of
arithmetic. The case $n = 2$ is the most transparent: in odd characteristic a curve in short Weierstrass form
$y^2 = f(x)$, with $f$ a separable cubic, has
\[
E(\FF_p)[2] = \{\mathcal{O}\} \cup \{(x,0) : f(x) = 0\},
\]
because negation on such a curve is $(x,y)\mapsto(x,-y)$, so a point is $2$-torsion precisely when $y=-y$, that is
$y=0$. Thus the group structure of $E[2]$ is \emph{literally} the factorisation type of $f$ over $\FF_p$: three
roots give a Klein four-group, one root gives $\ZZ/2$.

\subsection{The two families}

\textbf{The twist family (Sections \ref{sec:prelim}--\ref{sec:sum}).} Fix $a \in \FF_p^\times$ and put
\[
E_{a,d} : y^2 = x^3 - a d^2 x, \qquad d \in \FF_p^\times .
\]
These are the quadratic twists of $E_{a,1}$ by $d$; they all have $j$-invariant $1728$ and their point counts vary
substantially with $d$. Our results say the $2$-torsion does \emph{not} vary with $d$ at all.

\medskip
\noindent\textbf{The $j=0$ family (Section \ref{sec:psi3}).} Put $C_b : y^2 = x^3 + b$, $b \in \FF_p^\times$, with
$j$-invariant $0$. Its $3$-division polynomial is $\psi_3^{(b)}(x) = 3x^4 + 12bx$, whose roots are the
$x$-coordinates of the affine $3$-torsion. Here the count over $\FF_p$ is genuinely erratic --- and yet the sum
over $b$ is not.

\subsection{Statement of the main results}

All results are unconditional; $p$ always denotes a prime.

\begin{theorem}[Two-regime law for the $2$-torsion]\label{thm:A}
Let $p \neq 2$ and $a \in \FF_p^\times$. For every $d \in \FF_p^\times$,
\[
\#E_{a,d}(\FF_p)[2] =
\begin{cases} 4, & a \text{ a square in } \FF_p,\\ 2, & \text{otherwise,}\end{cases}
\]
and consequently
\[
\Sigma_a(p) := \sum_{d \in \FF_p^\times} \#E_{a,d}(\FF_p)[2] =
\begin{cases} 4(p-1), & a \text{ a square},\\ 2(p-1), & \text{otherwise.}\end{cases}
\]
\end{theorem}

\begin{theorem}[Group-theoretic form]\label{thm:B}
With $p \neq 2$ and $c = ad^2 \neq 0$: if $c$ is a square in $\FF_p$, the $2$-torsion subgroup of $y^2 = x^3 - cx$
over $\FF_p$ is isomorphic to $\ZZ/2 \times \ZZ/2$; if $c$ is a non-square, it is cyclic of order two and in
particular contains no Klein four-subgroup. As a Lagrange consequence, $4 \mid \#E(\FF_p)$ in the split regime and
$2 \mid \#E(\FF_p)$ in every regime.
\end{theorem}

\begin{theorem}[Reciprocity input and congruence criteria]\label{thm:C}
For a prime $p \notin \{2,3\}$, $3$ is a square modulo $p$ if and only if $p \equiv 1$ or $11 \pmod{12}$. Hence
\[
\Sigma_3(p) = \begin{cases} 4(p-1), & p \equiv 1, 11 \pmod{12},\\ 2(p-1), & p \equiv 5,7 \pmod{12}.\end{cases}
\]
Analogously, $\Sigma_2(p) = 4(p-1)$ iff $p \equiv 1,7 \pmod 8$, and $\Sigma_{-1}(p) = 4(p-1)$ iff $p\equiv 1\pmod 4$.
\end{theorem}

\begin{theorem}[Regime-independence of the summed $3$-division count]\label{thm:D}
For every prime $p \neq 2,3$,
\[
\sum_{b \in \FF_p^\times} \#\{x \in \FF_p : \psi_3^{(b)}(x) = 0\} = 2(p-1),
\]
independently of the residue of $p$ modulo $3$ --- even though for $p \equiv 2 \pmod 3$ every individual term
equals $2$, while for $p \equiv 1 \pmod 3$ the individual terms take the values $1$ and $4$.
\end{theorem}

\subsection{What the contrast means}

Theorems \ref{thm:A}--\ref{thm:C} and Theorem \ref{thm:D} are structurally parallel: both are summed root counts of
a division polynomial over a one-parameter family. But their content is entirely different.

In Theorem \ref{thm:A} the family parameter $d$ enters through $ad^2$, and squareness is invariant under
multiplication by a nonzero square. The sum is $(p-1)$ identical copies of a single arithmetic quantity, and the
Legendre symbol $\left(\frac{a}{p}\right)$ --- hence, via reciprocity, a congruence condition on $p$ --- passes
intact through the summation.

In Theorem \ref{thm:D} the family parameter $b$ enters through the translation $x^3 \mapsto x^3 + 4b$, and the map
$x \mapsto -x^3/4$ sends $\FF_p^\times$ onto the parameter space with total multiplicity $p-1$ regardless of its
fibre structure. Summing therefore counts the domain rather than the image, and the cubic-residue arithmetic
cancels identically.

The general moral: a summed fibre count over a family retains exactly those invariants that the family fails to
average away.

\section{Preliminaries}\label{sec:prelim}

Throughout, $p$ is a prime and $\FF_p = \ZZ/p\ZZ$, with $\FF_p^\times = \FF_p \setminus\{0\}$ of cardinality $p-1$.

\begin{definition}
An element $c \in \FF_p$ is a \emph{square} if $c = s^2$ for some $s \in \FF_p$. Note that $0$ is a square.
\end{definition}

\begin{lemma}[Nonvanishing of small constants]\label{lem:nonzero}
If $q$ is prime and $p \neq q$, the image of $q$ in $\FF_p$ is nonzero.
\end{lemma}
\begin{proof}
$q \equiv 0$ in $\FF_p$ means $p \mid q$; since both are prime this forces $p = q$.
\end{proof}

In particular $2 \neq 0$ and $3 \neq 0$ in $\FF_p$ for $p \notin \{2,3\}$, and then $4 = 2\cdot 2 \neq 0$ since
$\FF_p$ is a domain.

\begin{definition}
For $c \in \FF_p$ put $\Sqrtset(c) := \{x \in \FF_p : x^2 = c\}$.
\end{definition}

\begin{lemma}\label{lem:sqrtcount}
Let $p \neq 2$ and $c \in \FF_p$, $c \neq 0$. If $c$ is a square then $\#\Sqrtset(c) = 2$; if $c$ is not a square
then $\#\Sqrtset(c) = 0$.
\end{lemma}
\begin{proof}
The second claim is immediate. For the first, write $c = s^2$; then $s \neq 0$ since $c \neq 0$, and $s \neq -s$
because $2s = 0$ with $2 \neq 0$ would force $s = 0$. If $x^2 = s^2$ then $(x-s)(x+s) = 0$, so $x = \pm s$ in the
field $\FF_p$. Hence $\Sqrtset(c) = \{s,-s\}$.
\end{proof}

\begin{definition}\label{def:curve}
For $c \in \FF_p$ let $E_c$ denote the Weierstrass curve with coefficients $(a_1,a_2,a_3,a_4,a_6)=(0,0,0,-c,0)$,
i.e. $y^2 = x^3 - cx$, together with a point at infinity $\mathcal{O}$. For $p \neq 2$ and $c \neq 0$ the
discriminant $\Delta = 64c^3$ is nonzero, so $E_c$ is an elliptic curve and $E_c(\FF_p)$ is a finite abelian group.
\end{definition}

\begin{definition}
$E_c(\FF_p)[2] := \{P \in E_c(\FF_p) : P+P = \mathcal{O}\}$. This is a subgroup: it contains $\mathcal{O}$, is
closed under negation, and is closed under addition since $(P+Q)+(P+Q) = (P+P)+(Q+Q)$ in an abelian group.
\end{definition}

\section{The 2-division polynomial and the local count}

\begin{definition}
For $c \in \FF_p$ set $\psi_2^{(c)}(X) := X^3 - cX \in \FF_p[X]$.
\end{definition}

\begin{lemma}[Torsion criterion]\label{lem:torscrit}
Let $p \neq 2$ and let $P = (x,y)$ be an affine point of $E_c(\FF_p)$. Then $P+P = \mathcal{O}$ iff $y = 0$.
\end{lemma}
\begin{proof}
On $y^2 = f(x)$ negation is $-(x,y) = (x,-y)$, so $P+P=\mathcal{O}$ iff $P = -P$ iff $2y = 0$; since $2 \neq 0$ and
$\FF_p$ is a domain, this is $y = 0$.
\end{proof}

\begin{proposition}\label{prop:rootbij}
For $p \neq 2$ and $c \neq 0$, the affine $2$-torsion points of $E_c(\FF_p)$ are exactly the $(x,0)$ with
$\psi_2^{(c)}(x)=0$, and $(x,0)\mapsto x$ is a bijection onto the root set. Consequently
\[
\#E_c(\FF_p)[2] = 1 + \#\{x \in \FF_p : x^3 = cx\}.
\]
\end{proposition}
\begin{proof}
By Lemma \ref{lem:torscrit} an affine $2$-torsion point has $y=0$, and the curve equation gives
$0 = x^3 - cx$. Conversely a root $x$ yields a point $(x,0)$; it is nonsingular because the partial derivative
condition $3x^2 - c \neq 0$ holds at every root of the separable cubic $X(X^2-c)$ (its roots $0,\pm\sqrt c$ are
distinct in $\overline{\FF_p}$ as $c \neq 0$, $p \neq 2$). Injectivity is clear, and the $+1$ counts $\mathcal{O}$.
\end{proof}

\begin{lemma}\label{lem:cubicroots}
For $c \neq 0$, $\{x : x^3 = cx\} = \{0\} \sqcup \Sqrtset(c)$, so the root count is $1 + \#\Sqrtset(c)$.
\end{lemma}
\begin{proof}
$x^3 - cx = x(x^2-c)$; a root satisfies $x = 0$ or $x^2 = c$. The union is disjoint because $0 \in \Sqrtset(c)$
would give $c = 0$.
\end{proof}

\begin{theorem}[Local two-regime count]\label{thm:local}
Let $p \neq 2$ and $c \in \FF_p^\times$. If $c$ is a square then $\#E_c(\FF_p)[2] = 4$; if $c$ is not a square then
$\#E_c(\FF_p)[2] = 2$.
\end{theorem}
\begin{proof}
Combine Proposition \ref{prop:rootbij}, Lemma \ref{lem:cubicroots} and Lemma \ref{lem:sqrtcount}: the count is
$1 + 1 + \#\Sqrtset(c)$, which is $4$ or $2$. (A non-square is automatically nonzero.)
\end{proof}

\subsection{Factorisation type}

\begin{proposition}[Split factorisation]\label{prop:split}
If $c = s^2$ with $s \in \FF_p$ then $\psi_2^{(c)}(X) = X(X-s)(X+s)$ in $\FF_p[X]$, a product of three linear
factors, distinct whenever $c \neq 0$.
\end{proposition}
\begin{proof}
$X(X-s)(X+s) = X(X^2-s^2) = X^3 - cX$.
\end{proof}

\begin{proposition}[Non-split factorisation]\label{prop:nonsplit}
For any $c$, $\psi_2^{(c)}(X) = X(X^2-c)$; and if $c$ is not a square in $\FF_p$, then $X^2 - c$ is irreducible
over $\FF_p$.
\end{proposition}
\begin{proof}
The identity is an expansion. A polynomial of degree at most three over a field is reducible iff it has a root; a
root $x$ of $X^2 - c$ would give $x^2 = c$, contradicting non-squareness.
\end{proof}

Thus the splitting field of $\psi_2^{(c)}$ is $\FF_p$ in the split regime and $\FF_{p^2}$ in the non-split regime,
matching the two possible orders $4$ and $2$ of the rational $2$-torsion.

\section{The group-theoretic upgrade}

\begin{theorem}[Split regime: the $2$-torsion is Klein four]\label{thm:klein}
Let $p \neq 2$ and $c = s^2 \neq 0$ in $\FF_p$. Then
\[
E_c(\FF_p)[2] = \{\mathcal{O},\ (0,0),\ (s,0),\ (-s,0)\}
\]
is a group of order four of exponent two, hence isomorphic to $\ZZ/2 \times \ZZ/2$.
\end{theorem}
\begin{proof}
The listed set is the $2$-torsion by Proposition \ref{prop:rootbij} and Proposition \ref{prop:split}, and its four
elements are distinct: $s \neq 0$ since $c \neq 0$, and $s \neq -s$ since $p \neq 2$. Every element satisfies
$g+g = \mathcal{O}$, so the exponent divides $2$; the group is nontrivial, so the exponent is $2$. A group of order
$4$ and exponent $2$ is a two-dimensional $\FF_2$-vector space, hence $\cong \ZZ/2\times\ZZ/2$.
\end{proof}

\begin{theorem}[Non-split regime]\label{thm:nonsplitgroup}
If $p \neq 2$ and $c$ is a non-square, then $E_c(\FF_p)[2] = \{\mathcal{O},(0,0)\} \cong \ZZ/2$; in particular
$E_c(\FF_p)$ contains no Klein four-subgroup of $2$-torsion.
\end{theorem}
\begin{proof}
By Proposition \ref{prop:rootbij} and Lemma \ref{lem:cubicroots} the affine $2$-torsion consists of the roots of
$X(X^2-c)$, and $X^2-c$ has no roots. A Klein four-group has order $4 \neq 2$.
\end{proof}

\begin{corollary}[Divisibility of the point count]\label{cor:div}
Let $p \neq 2$ and $c \in \FF_p^\times$. Then $2 \mid \#E_c(\FF_p)$; and if $c$ is a square then
$4 \mid \#E_c(\FF_p)$.
\end{corollary}
\begin{proof}
$E_c(\FF_p)$ is finite and nonempty. The point $(0,0)$ has order exactly two, so $\langle (0,0)\rangle$ has order
two and Lagrange gives the first claim; the Klein four-subgroup of Theorem \ref{thm:klein} gives the second.
\end{proof}

Corollary \ref{cor:div} has practical bite: with $\#E_c(\FF_p) = p+1-t$ and $|t| \le 2\sqrt p$ (Hasse), part two
forces $t \equiv p+1 \pmod 4$, cutting the admissible trace values by a factor of four and guaranteeing a cofactor
divisible by $4$ in any cryptographic use of $E_c$ with $c$ a square.

\section{Twist invariance and the summed law}\label{sec:sum}

\begin{lemma}[Squareness is a twist invariant]\label{lem:twistinv}
Let $a,d \in \FF_p$ with $d \neq 0$. Then $ad^2$ is a square iff $a$ is.
\end{lemma}
\begin{proof}
If $a = s^2$ then $ad^2 = (sd)^2$. Conversely if $ad^2 = t^2$ then $a = (t/d)^2$, legitimate as $d$ is invertible.
\end{proof}

The content of Lemma \ref{lem:twistinv} is that the field over which the full $2$-torsion of $E_{a,d}$ becomes
rational, namely $\FF_p(\sqrt{ad^2}) = \FF_p(\sqrt a)$, is independent of $d$: all members of a quadratic twist
family share a single $2$-division field.

\begin{definition}
For $a \in \FF_p^\times$ set
$\Sigma_a(p) := \sum_{d \in \FF_p^\times} \#E_{a,d}(\FF_p)[2]$, with $E_{a,d} : y^2 = x^3 - ad^2x$.
\end{definition}

\begin{theorem}[General two-regime law; Theorem \ref{thm:A}]\label{thm:gen}
Let $p \neq 2$ and $a \in \FF_p^\times$. Then $\Sigma_a(p) = 4(p-1)$ if $a$ is a square in $\FF_p$, and
$\Sigma_a(p) = 2(p-1)$ otherwise.
\end{theorem}
\begin{proof}
Fix $d \neq 0$ and put $c = ad^2 \neq 0$. By Lemma \ref{lem:twistinv} $c$ is a square iff $a$ is, so by
Theorem \ref{thm:local} the $d$-th summand equals $4$ or $2$ independently of $d$. The index set has $p-1$
elements.
\end{proof}

\subsection{The reciprocity input}

\begin{lemma}\label{lem:mod3}
Let $p \neq 3$ be prime. Then $p \not\equiv 0 \pmod 3$, and the image of $p$ in $\FF_3$ is a square iff
$p \equiv 1 \pmod 3$.
\end{lemma}
\begin{proof}
The first claim is Lemma \ref{lem:nonzero}. For the second, $p \bmod 3 \in \{1,2\}$ and the squares in $\FF_3$ are
$\{0,1\}$.
\end{proof}

\begin{theorem}[Reciprocity criterion for $a=3$]\label{thm:recip3}
Let $p \notin \{2,3\}$ be prime. Then $3$ is a square modulo $p$ if and only if $p \equiv 1$ or $11 \pmod{12}$.
\end{theorem}
\begin{proof}
$p$ is odd, so $p \equiv 1$ or $3 \pmod 4$. Quadratic reciprocity for the pair $(p,3)$ gives: if $p\equiv 1\pmod4$
then $3$ is a square mod $p$ iff $p$ is a square mod $3$; if $p \equiv 3 \pmod 4$ then $3$ is a square mod $p$ iff
$p$ is \emph{not} a square mod $3$. Combining with Lemma \ref{lem:mod3}:
$p \equiv 1 \pmod{12}$ split; $p \equiv 5 \pmod{12}$ non-split; $p \equiv 7 \pmod{12}$ non-split;
$p \equiv 11 \pmod{12}$ split. By the Chinese Remainder Theorem these four residues exhaust the units mod $12$.
\end{proof}

\begin{corollary}[The mod-$12$ dichotomy]\label{cor:mod12}
For $p \notin \{2,3\}$, $\Sigma_3(p) = 4(p-1)$ if $p \equiv 1,11 \pmod{12}$ and $\Sigma_3(p) = 2(p-1)$ if
$p \equiv 5,7 \pmod{12}$.
\end{corollary}

\begin{theorem}[Other reciprocity inputs]\label{thm:other}
Let $p \neq 2$. Then $\Sigma_2(p) = 4(p-1)$ iff $p \equiv 1,7 \pmod 8$; and $\Sigma_{-1}(p) = 4(p-1)$ iff
$p \equiv 1 \pmod 4$ (the family being $y^2 = x^3 + d^2 x$).
\end{theorem}
\begin{proof}
Immediate from Theorem \ref{thm:gen} together with the classical supplementary laws: $2$ is a quadratic residue mod
$p$ iff $p \equiv \pm1 \pmod 8$, and $-1$ is one iff $p \equiv 1 \pmod 4$. The parameters are nonzero in $\FF_p$.
\end{proof}

The point of Theorem \ref{thm:other} is structural: the geometric content of the two-regime law is a single
sentence (Lemma \ref{lem:twistinv} plus Theorem \ref{thm:local}), and all the arithmetic variety --- mod $12$,
mod $8$, mod $4$ --- comes from the choice of reciprocity law used to evaluate one Legendre symbol.

