\section{The 3-division polynomial, and the collapse of the arithmetic}\label{sec:psi3}

\begin{definition}
For $b \in \FF_p$ put $\psi_3^{(b)}(X) := 3X^4 + 12bX \in \FF_p[X]$; its roots in $\overline{\FF_p}$ are the
$x$-coordinates of the nonzero $3$-torsion points of $C_b : y^2 = x^3 + b$.
\end{definition}

\begin{proposition}\label{prop:psi3fac}
$\psi_3^{(b)}(X) = 3X\,(X^3 + 4b)$.
\end{proposition}
\begin{proof}
$3X(X^3+4b) = 3X^4 + 12bX$.
\end{proof}

\begin{proposition}\label{prop:psi3root}
Let $3 \neq 0$ in $\FF_p$. Then for $x \in \FF_p$: $\psi_3^{(b)}(x) = 0$ iff $x = 0$ or $x^3 = -4b$.
\end{proposition}
\begin{proof}
$\psi_3^{(b)}(x) = 3x(x^3+4b)$; in a field a product vanishes iff a factor does, and $3 \neq 0$.
\end{proof}

\begin{proposition}\label{prop:psi3count}
Let $p \neq 2,3$ and $b \in \FF_p^\times$. Then
$\#\{x \in \FF_p : \psi_3^{(b)}(x) = 0\} = 1 + \#\{x \in \FF_p : x^3 = -4b\}$.
\end{proposition}
\begin{proof}
The root set is $\{0\} \cup \{x : x^3 = -4b\}$ by Proposition \ref{prop:psi3root}, and the union is disjoint since
$0^3 = 0 \neq -4b$ (as $4 \neq 0$ and $b \neq 0$).
\end{proof}

\subsection{Cubing in the two characteristics}

\begin{lemma}\label{lem:cubebij}
If $p \equiv 2 \pmod 3$, the map $x \mapsto x^3$ on $\FF_p$ is injective, hence bijective.
\end{lemma}
\begin{proof}
Choose $k \in \NN$ with $3k = 2(p-1)+1$; such $k$ exists because $2p - 1 \equiv 3 \equiv 0 \pmod 3$. For $x \neq 0$
Fermat gives $x^{p-1}=1$, so $(x^3)^k = x^{2(p-1)+1} = (x^{p-1})^2 x = x$; for $x = 0$ the identity is clear since
$k \neq 0$. Hence cubing has a left inverse and is injective, and an injective self-map of a finite set is
bijective.
\end{proof}

\begin{corollary}\label{cor:cube2mod3}
If $p \equiv 2 \pmod 3$, every $a \in \FF_p$ has exactly one cube root; hence by Proposition \ref{prop:psi3count}
every $C_b$ with $b \neq 0$ has exactly two rational $x$-coordinates of $3$-torsion.
\end{corollary}

If instead $p \equiv 1 \pmod 3$, the cyclic group $\FF_p^\times$ has order divisible by $3$, so it contains the
primitive cube roots of unity and cubing is exactly $3$-to-$1$ on $\FF_p^\times$. Then
$\#\{x : x^3 = -4b\}$ equals $3$ for the $(p-1)/3$ values of $b$ making $-4b$ a cube, and $0$ for the remaining
$2(p-1)/3$ values; local counts are therefore $4$ or $1$.

\subsection{The summed count}

\begin{theorem}[Regime-independent summed count; Theorem \ref{thm:D}]\label{thm:psi3sum}
Let $p \neq 2,3$. Then
\[
\sum_{b \in \FF_p^\times} \#\{x \in \FF_p : \psi_3^{(b)}(x) = 0\} = 2(p-1).
\]
\end{theorem}
\begin{proof}
By Proposition \ref{prop:psi3count} the sum equals
$(p-1) + \sum_{b \neq 0} \#\{x : x^3 = -4b\}$, so it suffices to show the second sum is $p-1$.
Consider $\varphi : \FF_p^\times \to \FF_p^\times$, $\varphi(x) = -x^3/4$; it is well defined since $x \neq 0$
implies $x^3 \neq 0$, and $4 \neq 0$. Partitioning the domain into fibres,
\[
p-1 = \#\FF_p^\times = \sum_{b \in \FF_p^\times} \#\varphi^{-1}(b).
\]
For each $b \neq 0$ the fibre $\varphi^{-1}(b)$ coincides with $\{x \in \FF_p : x^3 = -4b\}$: the equation
$-x^3/4 = b$ is equivalent to $x^3 = -4b$ after clearing the invertible denominator, and every solution is
automatically nonzero because $-4b \neq 0$. Substituting gives the claim, and the total is $2(p-1)$.
\end{proof}

\begin{remark}
The proof never asks how many cube roots a particular element has. It counts the set of pairs
$\{(b,x) : b \neq 0,\ x^3 = -4b\}$ and observes that projection to $x$ is a bijection onto $\FF_p^\times$, since
$b$ is determined by $x$. Projection to $b$ is the erratic direction, and only there is the cubic residue character
of $-4b$ --- hence $p \bmod 3$ --- visible. The summation, by fibering the other way, is blind to it.
\end{remark}

\begin{example}
At $p = 7 \equiv 1 \pmod 3$ the individual counts over $b = 1,\dots,6$ are $1,4,1,1,4,1$, summing to $12 = 2\cdot6$.
At $p = 11 \equiv 2 \pmod 3$ every individual count is $2$, and the sum is $20 = 2 \cdot 10$. Two entirely
different local pictures, the same global answer.
\end{example}

\section{Algorithms}

\begin{algorithmbox}[Regime of a twist family]
\emph{Input:} an odd prime $p$ and a parameter $a$ with $p \nmid a$.
\emph{Output:} $\Sigma_a(p)$ and the isomorphism type of the common $2$-torsion group.
\begin{enumerate}
\item Compute the Legendre symbol $\chi = \left(\frac{a}{p}\right)$, by Euler's criterion
$a^{(p-1)/2} \bmod p$ or by the binary Jacobi-symbol algorithm.
\item If $\chi = +1$, return $\bigl(4(p-1),\ \ZZ/2\times\ZZ/2\bigr)$.
\item Otherwise return $\bigl(2(p-1),\ \ZZ/2\bigr)$.
\end{enumerate}
\end{algorithmbox}

Complexity: $O(\log^2 p)$ bit operations with the reciprocity-based algorithm, versus $\Theta(p\log p)$ for naive
enumeration of the family. Correctness is Theorem \ref{thm:gen} with Theorems \ref{thm:klein} and
\ref{thm:nonsplitgroup}. For $a \in \{3,2,-1\}$ step $1$ reduces to a single residue test
($p \bmod 12 \in \{1,11\}$, $p \bmod 8 \in \{1,7\}$, $p \bmod 4 = 1$) by Theorems \ref{thm:recip3} and
\ref{thm:other}.

\begin{algorithmbox}[Klein four generators]
\emph{Input:} an odd prime $p$ and a quadratic residue $c \in \FF_p^\times$.
\emph{Output:} the four elements of $E_c(\FF_p)[2]$.
\begin{enumerate}
\item Compute a square root $s$ of $c$: if $p \equiv 3 \pmod 4$ take $s = c^{(p+1)/4}$, else run Tonelli--Shanks.
\item Return $\{\mathcal{O},(0,0),(s,0),(-s,0)\}$.
\end{enumerate}
\end{algorithmbox}

Correctness is Theorem \ref{thm:klein}; complexity is dominated by the modular square root.

\begin{algorithmbox}[Summed $3$-division count]
\emph{Input:} a prime $p \neq 2,3$.
\emph{Output:} the local counts $\#\{x : \psi_3^{(b)}(x) = 0\}$ for $b \in \FF_p^\times$ and their sum.
\begin{enumerate}
\item Build the cube table $T[x] = x^3 \bmod p$ for $x = 0,\dots,p-1$.
\item For each $b \in \{1,\dots,p-1\}$ count $m_b = \#\{x : T[x] = (-4b) \bmod p\}$ and record $1 + m_b$.
\item Return the list and its total, which is $2(p-1)$ by Theorem \ref{thm:psi3sum}.
\end{enumerate}
\end{algorithmbox}

Complexity $O(p)$. The output list is constant $=2$ when $p \equiv 2 \pmod 3$ and takes only the values $1$ and $4$
when $p \equiv 1 \pmod 3$, with exactly $(p-1)/3$ entries equal to $4$.

\section{Discussion and future directions}

\subsection{What was actually used}

\begin{itemize}
\item \emph{Geometry:} on $y^2 = f(x)$ in odd characteristic, $2$-torsion $=$ roots of $f$ plus one point at
infinity (Lemma \ref{lem:torscrit}).
\item \emph{Algebra:} $X^3 - cX = X(X^2-c)$, and a quadratic over a field is irreducible iff rootless
(Propositions \ref{prop:split}, \ref{prop:nonsplit}).
\item \emph{Invariance:} squareness is unchanged by multiplication by a nonzero square (Lemma \ref{lem:twistinv}).
\item \emph{Arithmetic:} one Legendre symbol, evaluated by reciprocity (Theorems \ref{thm:recip3},
\ref{thm:other}).
\end{itemize}

Only the last item is deep, and it is entirely classical. The first three are the reason the statement holds
unconditionally in both regimes with no exceptional primes beyond $p \in \{2,3\}$, which are excluded because
$2 = 0$ destroys Lemma \ref{lem:torscrit} and $3 = 0$ destroys the reciprocity input (respectively the factor $3$
in $\psi_3$).

\subsection{Sharpness}

Both values $4(p-1)$ and $2(p-1)$ occur for infinitely many $p$: by Dirichlet's theorem each of the four classes
$1,5,7,11 \bmod 12$ contains infinitely many primes with natural density $1/4$ among the primes, so
$\Sigma_3(p) = 4(p-1)$ for a set of primes of density $1/2$.

\subsection{Future directions}

\paragraph{Direction 1 --- Higher division-polynomial fibre dichotomy.}
For $n \ge 4$ the $n$-division polynomial $\psi_n$ of the twist family factors over the $n$-division field
$\QQ(E[n])$ rather than over a single quadratic field, and the summed fibre count should be governed by the
splitting type of $p$ in $\QQ(E[n])$ --- a non-abelian invariant for generic $E$.

\begin{conjecture}
For the family $E_{a,d} : y^2 = x^3 - ad^2x$ and each $n$, the sum
$\sum_{d \neq 0} \#\{x : \psi_n^{(d)}(x) = 0\}$ is a function of the Frobenius conjugacy class of $p$ in
$\Gal(\QQ(E[n])/\QQ)$ alone, and equals $(p-1)\,c_n(\Frob_p)$ for an explicit integer $c_n$.
\end{conjecture}

The key insight is that the twisting parameter $d$ acts on the fibres by a scaling that is a bijection of
$\FF_p^\times$, so the summed count only sees the isomorphism class of the splitting field, not the individual
twist --- precisely the mechanism isolated above for $n = 2$ and $n = 3$. The case $n = 2$ is settled
(Corollary \ref{cor:mod12}) and $n = 3$ exhibits regime-independence (Theorem \ref{thm:psi3sum}), so the general
statement can be tested against two proven anchors.

\paragraph{Direction 2 --- Klein-four density in twist families.}
\begin{conjecture}
For fixed squarefree $a$, the density of primes $p$ for which $E_a(\FF_p)[2] \cong \ZZ/2\times\ZZ/2$ is exactly
$1/2$, and the discrepancy $\#\{p \le X : \text{split}\} - \pi(X)/2$ is $O(X^{1/2+\varepsilon})$ under the
Generalized Riemann Hypothesis.
\end{conjecture}
The key insight is that the split condition proved here is exactly a quadratic-character condition on $a$, so the
density statement reduces to Chebotarev/Dirichlet for the single quadratic field $\QQ(\sqrt a)$, with the error
term controlled by the associated Dirichlet $L$-function. Theorem \ref{thm:gen} reduces the geometric condition to
the squareness of $a$ unconditionally, so the analytic input is completely isolated from the elliptic-curve
geometry.

\paragraph{Direction 3 --- Exponent-two subgroup classification.}
One can ask, for a fixed finite abelian group $G$ of exponent two, for which $p$ and which family members $G$
embeds into $E(\FF_p)$. For elliptic curves the answer is bounded ($E[2] \cong (\ZZ/2)^r$ with $r \le 2$), so the
classification here is complete for $n = 2$; the interesting version is for abelian surfaces and higher-dimensional
Jacobians, where the full $2$-torsion has rank up to $2g$ and the splitting behaviour of the corresponding
hyperelliptic model over $\FF_p$ replaces the single Legendre symbol by a cycle-type statistic in $S_{2g+2}$.

\paragraph{Direction 4 --- Effective ranges and record searches.}
The two-regime law makes it trivial to generate, for any target size, a curve in the family whose point count is
divisible by $4$ (choose $p \equiv \pm 1 \bmod 12$) or guaranteed not divisible by $4$ from the $2$-torsion (choose
$p \equiv 5,7 \bmod 12$). Whether the resulting families have unusual distributions of the cofactor
$\#E(\FF_p)/4$ --- in particular how often it is prime --- is an accessible experimental question with immediate
relevance to curve selection.

\subsection{Concluding remarks}

The two theorems that sit side by side --- a summed count that \emph{is} arithmetic (Theorem \ref{thm:gen}, with
the mod-$12$ refinement of Corollary \ref{cor:mod12}) and a summed count that \emph{is not}
(Theorem \ref{thm:psi3sum}) --- form a matched pair isolating a general principle: the arithmetic content of a
family-summed invariant is exactly what the family action fails to average away. In the $2$-torsion case the family
acts by scaling the coefficient by squares, and the quadratic character is an invariant of that action, so it
survives. In the $3$-division case the family sweeps the cube-translate through every nonzero value once, and
nothing survives. Both are the same computation with the same tools; only the group action differs.

